28	pub(crate) async fn run_and_capture_output<F, Fut, T>(func: F) -> (T, String)
29	where
30	    F: FnOnce() -> Fut,
31	    Fut: Future<Output = T>,
32	{
33	    let mut output = String::new();
34	
35	    // Capture both stdout and stderr to buffers, run the code and save to a string.
36	    let buf_stdout = gag::BufferRedirect::stdout();
37	    let buf_stderr = gag::BufferRedirect::stderr();
38	    let result = func().await;
39	
40	    if let Ok(mut buf_stdout) = buf_stdout {
41	        buf_stdout.read_to_string(&mut output).unwrap();
42	        drop(buf_stdout);
43	    }
44	
45	    if let Ok(mut buf_stderr) = buf_stderr {
46	        buf_stderr.read_to_string(&mut output).unwrap();
47	        drop(buf_stderr);
48	    }
49	
50	    if cfg!(windows) {
51	        // In windows output error and warning path files start with \\?\
52	        // We replace \ by / so tests can check unix paths only
53	        let regex = Regex::new(r"\\\\?\\(.*)").unwrap();
54	        output = regex
55	            .replace_all(output.as_str(), |caps: &Captures| {
56	                caps[1].replace('\\', "/")
57	            })
58	            .to_string();
59	    }
60	
61	    (result, output)
62	}
